/// The shell whose words the view says (client/web/README.md, 2.4).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Shell {
    Terminal,
    Browser,
}
#[derive(Clone, Debug)]
pub struct Words {
    /// The shell's minutes east of universal time (temper/docs/design/client/view.md, 6).
    pub zone_minutes: i32,
    pub shell: Shell,
    pub book: Phrasebook,
    pub language: u16,
    pub connector: u16,
    /// The checked joined bound of ordinary Name holes.
    pub name_bytes: u32,
}
// A refusal joins only this closed vocabulary, bounded numbers and a calendar
// clock: 256 bytes holds its longest three-sentence explanation whole.
const REFUSAL_BYTES: u32 = 256;
const SET_UP_FAILURE_BYTES: u32 = temper_client_domain::forge::forges::FAILURE_BYTES;
// Switcher paths join two Name holes, a slash, " +", and ten u32 digits (client/view.md, 3).
fn switcher_repository_bytes(joined: u32) -> Result<u32, Invalid> {
    joined.checked_mul(2).ok_or(Invalid::Overflow)?.checked_add(13).ok_or(Invalid::Overflow)
}
// Thirty-two 64-byte project names, each with room for the five-byte conjunction
// (client/pages/settings.md, 2).
const SETTINGS_PROJECT_NAMES_BYTES: u32 = 2208;
// Twenty items, six implicit kinds and six implicit sets, each within 200 bytes with words (client/pages/settings.md, 2).
const CLASSES_OBJECTS_BYTES: u32 = 6400;
// Six 40-byte set names, four commas and the last conjunction (client/forge/README.md, 4.1).
const APPROVAL_SET_NAMES_BYTES: u32 = 253;
const FOLLOW_WORDS: [Word; 12] = [
    Word::HowFollowMain,
    Word::HowFollowBranch,
    Word::HowFollowTouches,
    Word::HowFollowOwned,
    Word::HowFollowTitle,
    Word::HowFollowOwnerWord,
    Word::HowFollowCheck,
    Word::HowFollowStopped,
    Word::HowFollowStatus,
    Word::HowTiersTitle,
    Word::HowTiersWords,
    Word::HowTierChecks,
];
#[expect(clippy::too_many_lines, reason = "one table prices each phrase-specific input bound")]
fn hole_bytes(word: Word, kind: HoleKind, last: bool, joined: u32) -> Result<u32, Invalid> {
    // Sixteen area names and Anything else, joined in a role's card head (team.md, 1).
    if word == Word::TeamOwnsSince {
        return Ok(temper_client_protocol_wire::v1::CEILINGS
            .area_row_name
            .saturating_add(2)
            .saturating_mul(temper_client_protocol_wire::v1::CEILINGS.findings_areas)
            .saturating_add(19)
            .max(joined));
    }
    if [Word::TeamAreaLede, Word::TeamHands, Word::TeamHand, Word::TeamInRole].contains(&word) {
        return Ok(joined.max(262));
    }
    if word == Word::AllHomeFollowChip {
        return Ok(temper_client_protocol_wire::v1::CEILINGS.follow_view_source);
    }
    if FOLLOW_WORDS.contains(&word) {
        let bounds = temper_client_protocol_wire::v1::CEILINGS;
        let paths = bounds
            .follow_source_paths_item
            .checked_add(4)
            .ok_or(Invalid::Overflow)?
            .checked_mul(bounds.follow_source_paths)
            .ok_or(Invalid::Overflow)?;
        let tiers = bounds
            .card_name
            .checked_add(bounds.fact_value)
            .ok_or(Invalid::Overflow)?
            .checked_add(5)
            .ok_or(Invalid::Overflow)?
            .checked_mul(bounds.branch_path_stops)
            .ok_or(Invalid::Overflow)?;
        let branch =
            bounds.follow_view_source.checked_add(bounds.follow_view_source_branch).ok_or(Invalid::Overflow)?;
        return joined
            .max(paths)
            .max(tiers)
            .max(branch)
            .max(bounds.follow_check_workflow)
            .max(bounds.follow_view_stopped_some)
            .checked_add(32)
            .ok_or(Invalid::Overflow);
    }
    if [Word::ClassesDecide, Word::ClassesAsk, Word::ClassesAskAway, Word::HowReachAwayBut].contains(&word) {
        return Ok(CLASSES_OBJECTS_BYTES);
    }
    if word == Word::ApprovalSets {
        return Ok(APPROVAL_SET_NAMES_BYTES);
    }
    // Eight 64-byte names, conjunctions and the count of others; both parts fit together.
    if [
        Word::ApprovalJoin,
        Word::ApprovalAnd,
        Word::ApprovalOr,
        Word::ApprovalSigned,
        Word::ApprovalCanGive,
        Word::ApprovalWhoBoth,
        Word::ApprovalWhoEnd,
    ]
    .contains(&word)
    {
        return Ok(1280);
    }
    if word == Word::ClassesSet {
        return Ok(if last { 490 } else { 40 });
    }
    if word == Word::ViewAsking || word == Word::ViewFailed {
        return Ok(512);
    }
    if word == Word::ViewPath || word == Word::ViewRepositoryPath {
        return Ok(if last && word == Word::ViewRepositoryPath { 2048 } else { 1024 });
    }
    if word == Word::ToastWayUsed || word == Word::ToastWayKept {
        return Ok(temper_client_protocol_wire::v1::CEILINGS.stock_way_name);
    }
    if word == Word::SettingsProposalTitle {
        return Ok(SETTINGS_PROJECT_NAMES_BYTES);
    }
    // A work argument admits 256 bytes plus a from-line suffix and its number (3.5).
    if kind == HoleKind::Name
        && [
            Word::WorkReadArgument,
            Word::WorkListedArgument,
            Word::WorkWroteArgument,
            Word::WorkEditedArgument,
            Word::WorkRemovedArgument,
            Word::WorkSearchedArgument,
            Word::WorkRanArgument,
            Word::WorkListing,
            Word::WorkWriting,
            Word::WorkEditing,
            Word::WorkRemoving,
            Word::WorkSearchingFiles,
            Word::WorkRunning,
            Word::WorkReadPage,
            Word::WorkSearched,
            Word::WorkChecked,
            Word::WorkReading,
            Word::WorkSearching,
            Word::WorkChecking,
            Word::WorkFromLine,
            Word::WorkFailedOut,
            Word::WorkRepeated,
            Word::WorkNumber,
        ]
        .contains(&word)
    {
        return Ok(288);
    }
    // The toast wraps the outgoing choice or the reply label (3.5).
    if word == Word::ToastAnswered {
        return temper_client_protocol_wire::CUE_BYTES.checked_add(14).ok_or(Invalid::Overflow);
    }
    if word == Word::AnsweredReply {
        return Ok(temper_client_protocol_wire::CUE_BYTES);
    }
    // A landed draft names its complete directory, or the root repository and slash.
    if word == Word::WorkLandedIn {
        let bounds = temper_client_protocol_wire::v1::CEILINGS;
        let name = bounds.landed_draft_name.checked_add(1).ok_or(Invalid::Overflow)?;
        return Ok(name.max(bounds.landed_draft_path));
    }
    // Changes names the wire's complete repository and branch (client/forge/records.md).
    if word == Word::ChangesQueueNamed {
        return Ok(if last {
            temper_client_protocol_wire::v1::CEILINGS.changes_queue_branch
        } else {
            temper_client_protocol_wire::v1::CEILINGS.changes_queue_repository
        });
    }
    if [Word::ChangesNone, Word::ChangesOne, Word::ChangesMany].contains(&word) && last
        || [Word::ChangesLede, Word::ChangesRed].contains(&word)
        || word == Word::ChangesMoved && !last
    {
        return Ok(temper_client_protocol_wire::v1::CEILINGS.changes_panel_landing);
    }

    // Copy titles retain every 100-byte org, slash, 100-byte name, comma and space (3.5).
    if word == Word::HomeCopiesIn && !last {
        return temper_client_protocol_wire::FIRST_COPIES.checked_mul(203).ok_or(Invalid::Overflow);
    }
    if word == Word::HomeCopyOffer
        || word == Word::HomeCopyIn && !last
        || word == Word::HomeCopying
        || word == Word::HomeMaking
    {
        return Ok(joined.max(512));
    }
    if word == Word::SwitcherRow && last {
        return switcher_repository_bytes(joined);
    }
    if word == Word::AdminHost {
        return Ok(temper_client_domain::forge::change::ADDRESS_BYTES);
    }
    if word == Word::SignInForgeAt || word == Word::AuthorizeContinuing || word == Word::SignInSignedOut {
        return Ok(joined.max(300));
    }
    if [
        Word::ForgeFetchFailed,
        Word::ForgePrepareFailed,
        Word::ForgeRunFailed,
        Word::ForgeConnectFailed,
        Word::ForgeSetupFailed,
    ]
    .contains(&word)
    {
        return Ok(SET_UP_FAILURE_BYTES);
    }
    // Bound clauses hold grouped u64 figures, charter names and a clock, independent of document text (5.5).
    if kind == HoleKind::Name
        && [
            Word::BoundTurns,
            Word::BoundTime,
            Word::BoundWaiting,
            Word::BoundChecks,
            Word::BoundWindow,
            Word::BoundOutput,
            Word::BoundSpend,
            Word::BoundMessage,
            Word::BoundInbox,
            Word::BoundUnacknowledged,
            Word::BoundLargest,
            Word::BoundQuickest,
            Word::BoundRefusedAt,
            Word::BoundTakes,
        ]
        .contains(&word)
    {
        return Ok(32);
    }
    if word == Word::PlaygroundGroupFailed {
        return Ok(temper_client_domain::forge::PLAYGROUND_WHY_BYTES);
    }
    if kind == HoleKind::Name
        && (word == Word::RefusalSentences
            || word == Word::WaitRefused
            || word == Word::BoundWorker
            || word == Word::BoundEngine)
    {
        return Ok(REFUSAL_BYTES);
    }
    if word == Word::PlaygroundRepository
        || word == Word::ForgePlaygroundSummary
        || word == Word::PlaygroundAdoptionFailed
    {
        return Ok(temper_client_domain::forge::PLAYGROUND_FIELD_BYTES);
    }
    if word == Word::BylineTask && kind == HoleKind::Name {
        // Two shown names, the Anthropic prefix, and the effort separator.
        let names = joined.min(MODEL_SHOWN).checked_mul(2).ok_or(Invalid::Overflow)?;
        return names.checked_add(12).ok_or(Invalid::Overflow);
    }
    let model_name = joined.min(MODEL_SHOWN);
    if word == Word::ModelEffort {
        // The closed line prefixes an Anthropic shown name with "Claude ".
        return model_name.checked_add(7).ok_or(Invalid::Overflow);
    }
    if last && [Word::UsingModel, Word::UsingKey, Word::UsingPlan, Word::UsingProgram].contains(&word) {
        let doubled = model_name.checked_mul(2).ok_or(Invalid::Overflow)?;
        return doubled.checked_add(3).ok_or(Invalid::Overflow);
    }
    if kind == HoleKind::Name
        && [
            Word::FindingFrom,
            Word::FindingFacts,
            Word::FindingHanded,
            Word::FindingNotYours,
            Word::FindingNoAreaRefused,
            Word::FindingNoSuchArea,
        ]
        .contains(&word)
    {
        // A refusal names sixteen 32-byte areas, separated by comma-space.
        return Ok(joined.max(542));
    }
    Ok(if kind == HoleKind::Name { joined } else { 0 })
}
fn english_language(
    connector: u16,
    text: u32,
    shell: Shell,
    joined: u32,
) -> Result<(List<PhraseShape>, Language), Invalid> {
    // The declaration writer must be able to measure vocabulary growth before
    // the checked production capacities have been regenerated.
    #[cfg(test)]
    let capacity = PHRASES.checked_add(64).expect("declaration headroom");
    #[cfg(not(test))]
    let capacity = PHRASES;
    let mut shapes = List::with_capacity(capacity);
    let mut phrases = List::with_capacity(capacity);
    for word in ALL {
        let (literals, kinds) = english(word, shell);
        let mut holes = List::with_capacity(4);
        let mut segments = List::with_capacity(9);
        for (index, literal) in literals.iter().enumerate() {
            segments.push(Segment::Text(copy_of(literal))).expect("closed English segments fit");
            if let Some(kind) = kinds.get(index) {
                holes
                    .push(HoleShape {
                        kind: *kind,
                        bytes: hole_bytes(word, *kind, index.checked_add(1) == Some(kinds.len()), joined)?,
                    })
                    .expect("four holes fit");
                segments
                    .push(Segment::Hole { index: u16::try_from(index).expect("four hole indices fit"), kind: *kind })
                    .expect("closed segments fit");
            }
        }
        let id = word.id(connector);
        let plural = if word == Word::WaitingForDelegates || word == Word::ChatDelegates { Some(0) } else { None };
        shapes.push(PhraseShape { id, holes: holes.into_boxed(), plural }).expect("closed shapes fit");
        let other = Form { class: PluralClass::Other, segments: segments.into_boxed() };
        let forms: Box<[Form]> = if word == Word::WaitingForDelegates || word == Word::ChatDelegates {
            Box::new([
                Form {
                    class: PluralClass::One,
                    segments: Box::new([
                        Segment::Text(copy_of(if word == Word::ChatDelegates { b"" } else { b"waiting on " })),
                        Segment::Hole { index: 0, kind: HoleKind::Number },
                        Segment::Text(copy_of(b" delegate")),
                    ]),
                },
                other,
            ])
        } else {
            Box::new([other])
        };
        phrases.push(Phrase { id, forms }).expect("closed phrases fit");
    }
    for word in jig_client::words::ALL {
        shapes.push(temper_client_domain::words::shape(word, text)).expect("jig word shapes fit");
    }
    for phrase in jig_language().phrases {
        phrases.push(phrase).expect("jig words fit");
    }
    accounts::extend(&mut shapes, &mut phrases, joined, text);
    cards::extend(text, &mut shapes, &mut phrases);
    terminal::extend(&mut shapes, &mut phrases);
    temper_client_domain::forge::words::extend(connector, text, &mut shapes, &mut phrases);
    temper_client_domain::forge::words::extend_change(connector, &mut shapes, &mut phrases);
    resource_phrases(connector, joined, &mut shapes, &mut phrases);
    let language = Language {
        plural: PluralRule::English,
        span_unit: SpanUnit::Seconds,
        wall: WallFormat::Seconds,
        phrases: phrases.into_boxed(),
    };
    Ok((shapes, language))
}

#[cfg(test)]
pub(crate) fn english_declarations() -> [(&'static str, u64, u64); 3] {
    let mut most_phrases = 0_u64;
    let mut most_segments = 0_u64;
    let mut most_text = 0_u64;
    for shell in [Shell::Browser, Shell::Terminal] {
        let (shapes, language) = english_language(1, 256, shell, 513).expect("bounded English");
        let mut segments = 0_u64;
        let mut text = 0_u64;
        for phrase in &language.phrases {
            for form in &phrase.forms {
                segments = segments.checked_add(skein_lib::len_u64(form.segments.len())).expect("bounded English");
                for segment in &form.segments {
                    match segment {
                        Segment::Text(bytes) => {
                            text = text.checked_add(skein_lib::len_u64(bytes.len())).expect("bounded English");
                        }
                        Segment::Hole { .. } => {}
                    }
                }
            }
        }
        most_phrases = most_phrases.max(u64::from(shapes.len()));
        most_segments = most_segments.max(segments);
        most_text = most_text.max(text);
    }
    [
        ("const PHRASES: u32 = ", u64::from(PHRASES), most_phrases),
        ("const SEGMENTS: u32 = ", u64::from(SEGMENTS), most_segments),
        ("const ENGLISH_BYTES: u32 = ", u64::from(ENGLISH_BYTES), most_text),
    ]
}

impl Words {
    /// The shell's minutes east of universal time (temper/docs/design/client/view.md, 6).
    pub fn set_zone_minutes(&mut self, zone_minutes: i32) {
        self.zone_minutes = zone_minutes;
    }
    fn local_nanos(&self, at: skein_lib::Wall) -> i128 {
        let offset = i128::from(self.zone_minutes).checked_mul(i128::from(MINUTE)).expect("i32 minutes fit i128");
        i128::from(at.as_nanos()).checked_add(offset).expect("wall and i32 minutes fit i128")
    }
    /// The calendar day in the person's zone, including before the epoch.
    #[must_use]
    pub fn calendar_day(&self, at: skein_lib::Wall) -> i64 {
        i64::try_from(self.local_nanos(at).div_euclid(i128::from(DAY))).expect("wall and i32 minutes' days fit i64")
    }

    /// The configured playground model's identifier has its own display name (client/pages/welcome.md, 2).
    #[must_use]
    pub fn model_name(&self, name: &[u8]) -> Box<[u8]> {
        if name == SCRIPTED_MODEL { self.say(Word::PlaygroundModelName, &[]) } else { copy_of(name) }
    }

    pub fn english(connector: u16, text: u32, shell: Shell) -> Result<Words, Invalid> {
        let joined = match text.checked_mul(2) {
            Some(bytes) => match bytes.checked_add(1) {
                Some(bytes) => bytes,
                None => return Err(Invalid::Overflow),
            },
            None => return Err(Invalid::Overflow),
        };
        let (shapes, language) = english_language(connector, text, shell, joined)?;
        let limits = PhraseLimits {
            languages: 1,
            phrases: PHRASES,
            holes: 4,
            // Setup fields and first repository need 28 more segments; the playground's start 15.
            segments: SEGMENTS,
            text_bytes: ENGLISH_BYTES,
            // Whole playground requests keep their supplied bound.
            hole_bytes: joined
                .max(hole_bytes(Word::HowFollowMain, HoleKind::Name, false, joined)?)
                .max(switcher_repository_bytes(joined)?)
                .max(SETTINGS_PROJECT_NAMES_BYTES)
                .max(CLASSES_OBJECTS_BYTES)
                .max(temper_client_protocol_wire::CUE_BYTES.checked_add(14).ok_or(Invalid::Overflow)?)
                .max(temper_client_protocol_wire::FIRST_COPIES.checked_mul(203).ok_or(Invalid::Overflow)?)
                .max(temper_client_domain::forge::PLAYGROUND_FIELD_BYTES)
                .max(temper_client_domain::forge::PLAYGROUND_WHY_BYTES)
                .max(temper_client_domain::forge::OWNED_PASSWORD_BYTES)
                .max(SET_UP_FAILURE_BYTES)
                .max(temper_client_domain::forge::change::ADDRESS_BYTES),
        };
        let book = Phrasebook::load(shapes.into_boxed(), Box::new([language]), &limits)?;
        Ok(Words { zone_minutes: 0, shell, book, language: 0, connector, name_bytes: joined })
    }
    #[must_use]
    pub fn say(&self, word: Word, holes: &[Hole]) -> Box<[u8]> {
        self.book.say(self.language, word.id(self.connector), holes).expect("checked forge phrase").text
    }
    #[must_use]
    pub fn deadline(&self, at: skein_lib::Wall) -> Box<[u8]> {
        let word = if at.as_secs() % 86_400 == 0 { Word::BudgetDeadlineDate } else { Word::BudgetDeadlineMoment };
        self.say(word, &[Hole::Wall(at)])
    }
    #[must_use]
    pub fn say_word(&self, word: jig_client::words::Word, holes: &[Hole]) -> Box<[u8]> {
        self.book.say(self.language, word.id(), holes).expect("checked jig word").text
    }
    /// A run's supplied placement time in absolute UTC.
    #[must_use]
    pub fn run_started(&self, at: skein_lib::Wall) -> Box<[u8]> {
        self.say(Word::RunStarted, &[Hole::Name(copy_of(&chat_clock(at)))])
    }

    pub fn text(&self, builder: &mut Builder, word: Word, holes: &[Hole]) {
        builder.text(Run::Plain, &self.say(word, holes));
    }
    pub fn resource_text(
        &self,
        builder: &mut Builder,
        word: temper_client_domain::forge::words::ResourceWord,
        holes: &[Hole],
    ) {
        let text = self.book.say(self.language, word.id(self.connector), holes).expect("checked resource phrase").text;
        builder.text(Run::Plain, &text);
    }
    #[must_use]
    pub fn path_bytes(&self) -> u32 {
        self.book
            .capacity(temper_client_domain::forge::words::ResourceWord::Path.id(self.connector))
            .expect("checked path word")
    }
    #[must_use]
    pub fn capacity(&self) -> Option<u32> {
        Some(self.ordinary_capacity()?.max(self.classes_capacity()?).max(self.follows_capacity()?))
    }
    /// Grouped classes occur only in Settings and a proposal's items (client/pages/settings.md, 2).
    pub(crate) fn classes_capacity(&self) -> Option<u32> {
        let mut most = 0;
        for word in [Word::ClassesDecide, Word::ClassesAsk, Word::ClassesAskAway, Word::HowReachAwayBut] {
            most = most.max(self.book.capacity(word.id(self.connector))?);
        }
        Some(most)
    }
    /// Landing boxes are priced only on How work runs (client/pages/settings.md, 2).
    pub(crate) fn follows_capacity(&self) -> Option<u32> {
        let mut most = 0;
        for word in FOLLOW_WORDS {
            most = most.max(self.book.capacity(word.id(self.connector))?);
        }
        Some(most)
    }
    pub(crate) fn ordinary_capacity(&self) -> Option<u32> {
        let mut most = 0;
        for word in ALL {
            if FOLLOW_WORDS.contains(&word)
                || [Word::ClassesDecide, Word::ClassesAsk, Word::ClassesAskAway, Word::HowReachAwayBut].contains(&word)
            {
                continue;
            }
            most = most.max(self.book.capacity(word.id(self.connector))?);
        }
        for word in jig_client::words::ALL {
            most = most.max(self.book.capacity(word.id())?);
        }
        Some(most.max(forge::capacity(self)?).max(accounts::capacity(self)?))
    }
}
